def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator is the constant column whose value differs from the
    # dominant colors on both sides.
    candidates = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    sep = max(candidates, key=lambda c: (
        c > 0 and c < w - 1,
        len(set(grid[r][c] for r in range(h))),
        c
    ))
    left = [grid[r][:sep] for r in range(h)]
    right = [grid[r][sep + 1:] for r in range(h)]

    def mode(rows):
        counts = {}
        for row in rows:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        return max(counts, key=counts.get)

    left_bg, right_bg = mode(left), mode(right)
    width = min(sep, w - sep - 1)
    return [
        [0 if left[r][c] != left_bg or right[r][c] != right_bg else 3
         for c in range(width)]
        for r in range(h)
    ]
